"""Build a static review candidate. --production changes indexing only; never deploys."""
from pathlib import Path
import argparse, json, re, shutil, html
ROOT=Path(__file__).resolve().parent
REPO=ROOT.parent
p=argparse.ArgumentParser();p.add_argument('--production',action='store_true');p.add_argument('--output',type=Path,default=REPO/'previews/candidate-v3');args=p.parse_args()
out=args.output.resolve();out.mkdir(parents=True,exist_ok=True)
systems=json.loads((ROOT/'systems.json').read_text())
slugs=['agentguard','foundationcentar','enterprise-hybrid-rag','agent-eval','agentvault','pharma-intelligence-os']
for s,slug in zip(systems,slugs):s['slug']=slug
E=html.escape
ORIGIN='https://wedocare-global.com'
def metadata(title,description,path,software=None):
 url=ORIGIN+path
 org={'@context':'https://schema.org','@type':'Organization','name':'We Do Care Global','url':ORIGIN+'/','logo':ORIGIN+'/logo.jpg','sameAs':['https://github.com/WeDoCareGlobal','https://orcid.org/0009-0009-8515-2727']}
 data=org if not software else {'@context':'https://schema.org','@type':'SoftwareSourceCode','name':software['name'],'description':software['desc'],'codeRepository':f"https://github.com/WeDoCareGlobal/{software['repo']}",'url':url,'identifier':f"https://doi.org/10.5281/zenodo.{software['doi']}",'author':{'@type':'Person','name':'Emir Perla','sameAs':'https://orcid.org/0009-0009-8515-2727'}}
 return f'''<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)}</title><meta name="description" content="{E(description,quote=True)}"><meta name="robots" content="{'index,follow' if args.production else 'noindex,nofollow'}"><link rel="canonical" href="{url}"><meta name="theme-color" content="#060a10"><meta property="og:type" content="website"><meta property="og:site_name" content="We Do Care Global"><meta property="og:title" content="{E(title,quote=True)}"><meta property="og:description" content="{E(description,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{ORIGIN}/brand-poster.jpg"><meta property="og:image:width" content="1280"><meta property="og:image:height" content="720"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="logo.jpg"><link rel="stylesheet" href="style.css"><script type="application/ld+json">{json.dumps(data)}</script>'''
def card(s,i):
 return f'''<article class="card" data-group="{s['group']}"><div class="card-top"><span>0{i+1} / {E(s['category'].upper())}</span><span>↗</span></div><div class="glyph" aria-hidden="true">{s['icon']}</div><h3><a href="{s['slug']}.html">{E(s['name'])}</a></h3><p>{E(s['desc'])}</p><div class="card-bottom"><span>PUBLISHED PORTFOLIO</span><a href="{s['slug']}.html">Explore system ↗</a></div></article>'''
s=(ROOT/'home.template.html').read_text()
s=re.sub(r'<head>.*?</head>','<head>'+metadata('We Do Care Global — Intelligence without blind spots','Six open engineering systems for AI security, governance, retrieval, evaluation, assurance and regulatory intelligence.','/')+'</head>',s,flags=re.S)
s=s.replace('<div class="cards" id="cards"></div>','<div class="cards" id="cards">'+''.join(card(x,i) for i,x in enumerate(systems))+'</div>')
s=s.replace('<div class="recommendation" id="recommendation" aria-live="polite"></div>', '<div class="recommendation" id="recommendation" aria-live="polite"><div class="eyebrow gold">YOUR STARTING POINT / SECURITY</div><h3>AgentGuard</h3><p>'+E(systems[0]['use'])+'</p><a class="button" href="agentguard.html">Explore AgentGuard ↗</a></div>')
s=re.sub(r'<dialog.*?</dialog>','',s,flags=re.S)
s=s.replace('style.css?v=2','style.css').replace('app.js?v=2','app.js')
s=s.replace('<nav aria-label="Main navigation">','<nav id="main-nav" aria-label="Main navigation">').replace('aria-label="Toggle navigation"','aria-controls="main-nav" aria-label="Toggle navigation"')
s=s.replace(' autoplay muted loop',' muted loop').replace(' preload="metadata"',' preload="none"')
s=s.replace('<button id="motion-toggle"','<button hidden id="motion-toggle"')
s=s.replace('Pause motion Ⅱ','Play motion ▷').replace('Pause brand animation','Play brand animation')
s=s.replace('<form id="contact-form">','<form id="contact-form" action="https://formsubmit.co/emir@wedocare-global.com" method="POST"><input type="hidden" name="_subject" value="We Do Care Global — website inquiry"><input type="text" name="_honey" tabindex="-1" autocomplete="off" class="honeypot" aria-hidden="true"><input type="hidden" name="_captcha" value="true">')
s=s.replace('This preview prepares an email in your mail app. It does not send or store your details. Please omit confidential information.','Submitting sends your inquiry to FormSubmit for delivery to We Do Care Global. Please omit confidential information.')
s=s.replace('<button class="button primary" type="submit">Prepare your inquiry','<label class="consent"><input type="checkbox" name="consent" required value="agreed"> I agree to processing of this inquiry through FormSubmit. <a href="privacy.html">Read the privacy notice.</a></label><button class="button primary" type="submit">Send inquiry')
s=s.replace('<p id="form-status" role="status"></p>','<p class="form-note">If submission fails, email <a href="mailto:emir@wedocare-global.com">emir@wedocare-global.com</a> directly.</p>')
s=s.replace('<div class="filters"','<div hidden class="filters"').replace('<div class="choices"','<div hidden class="choices"')
s=s.replace('<a href="#contact">Contact ↗</a>','<a href="#contact">Contact ↗</a><a href="privacy.html">Privacy</a>')
if args.production:s=re.sub(r'<div class="preview">.*?</div>','',s,count=1,flags=re.S)
(out/'index.html').write_text(s)
header=re.search(r'<header>.*?</header>',s,re.S).group().replace('href="#"','href="index.html"').replace('href="#','href="index.html#')
footer=re.search(r'<footer.*?</footer>',s,re.S).group().replace('href="#"','href="index.html"').replace('href="#','href="index.html#')
banner='' if args.production else '<div class="preview">REVIEW CANDIDATE · NOT PUBLISHED TO PRODUCTION</div>'
def page(title,description,path,body,software=None):return '<!doctype html><html lang="en"><head>'+metadata(title,description,path,software)+'</head><body><a class="skip" href="#main">Skip to content</a>'+banner+header+'<main id="main">'+body+'</main>'+footer+'<script src="app.js"></script></body></html>'
for i,x in enumerate(systems):
 related=[z for z in systems if z!=x and z['group']==x['group']]
 body=f'''<section class="product-hero wrap"><a class="back" href="index.html#systems">← All six systems</a><div class="eyebrow gold">0{i+1} / {E(x['category'].upper())}</div><div class="glyph">{x['icon']}</div><h1>{E(x['name'])}</h1><p class="intro">{E(x['desc'])}</p><div class="actions"><a class="button primary" href="https://wedocareglobal.github.io/{x['repo']}/" target="_blank" rel="noopener">Open project demo ↗</a><a class="button" href="https://github.com/WeDoCareGlobal/{x['repo']}" target="_blank" rel="noopener">Inspect GitHub ↗</a></div></section><section class="product-body wrap"><article><div class="eyebrow gold">WHERE TO START</div><h2>Put the use case first.</h2><p>{E(x['use'])}</p><h3>Published project focus</h3><ul>{''.join('<li>'+E(f)+'</li>' for f in x['focus'])}</ul><h3>Before an operational deployment</h3><p>Review the source, configuration and test evidence against your environment. Establish ownership, access boundaries and acceptance criteria before handling real workloads.</p><aside class="disclaimer"><h3>Known scope</h3><p>{E(x['note'])}</p></aside></article><aside class="source-panel"><div class="eyebrow gold">FOLLOW THE EVIDENCE</div><h3>Source & publication</h3><a href="https://github.com/WeDoCareGlobal/{x['repo']}" target="_blank" rel="noopener">GitHub repository ↗</a><a href="https://doi.org/10.5281/zenodo.{x['doi']}" target="_blank" rel="noopener">Zenodo · {x['doi']} ↗</a><a href="https://orcid.org/0009-0009-8515-2727" target="_blank" rel="noopener">Creator's ORCID ↗</a><p>Publication references are carried from the public portfolio. A publication record is not a production-readiness certification.</p><a class="button" href="index.html#contact">Discuss this system ↗</a></aside></section><section class="related wrap"><div class="eyebrow gold">EXPLORE THE ECOSYSTEM</div><h2>Continue with {E(related[0]['name'])}.</h2><p>{E(related[0]['desc'])}</p><a class="button" href="{related[0]['slug']}.html">Explore related system ↗</a></section>'''
 (out/(x['slug']+'.html')).write_text(page(x['name']+' | We Do Care Global',x['desc'],'/'+x['slug']+'.html',body,x))
body='''<section class="legal wrap"><div class="eyebrow gold">CONTACT PRIVACY</div><h1>Your inquiry.</h1><p>The website contact form collects your name, business email, selected interest and message so We Do Care Global can respond. Contact: <a href="mailto:emir@wedocare-global.com">emir@wedocare-global.com</a>.</p><h2>Where your message goes</h2><p>When you choose Send inquiry, your browser submits these fields to FormSubmit, a third-party form delivery service. The submission flow may include CAPTCHA verification. Messages are intended for the business mailbox shown above.</p><p>Read <a href="https://formsubmit.co/privacy.pdf" target="_blank" rel="noopener">FormSubmit's privacy policy</a> before submitting. You may email us directly instead. Do not submit passwords, patient information, credentials or other confidential data.</p><h2>Other requests from your browser</h2><p>This candidate uses Google Fonts with local system-font fallbacks. Loading those fonts contacts Google's servers. Video, logo and poster assets are served with the website. This candidate includes no analytics tracker.</p><h2>Questions and requests</h2><p>Contact emir@wedocare-global.com to ask about your inquiry or request correction or deletion. This notice describes this website's current contact flow; it does not promise specific retention periods or regulatory certifications.</p></section>'''
(out/'privacy.html').write_text(page('Contact privacy | We Do Care Global','How website inquiries are processed by We Do Care Global and FormSubmit.','/privacy.html',body))
for name in ['style.css','app.js']:shutil.copyfile(ROOT/name,out/name)
for name in ['logo.jpg','brand-motion.mp4','brand-poster.jpg']:shutil.copyfile(REPO/'previews/approved-v2'/name,out/name)
# Safe review default; production build produces crawlable URLs but does not publish them.
paths=['/']+['/'+x+'.html' for x in slugs]+['/privacy.html']
(out/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+ORIGIN+x+'</loc></url>' for x in paths)+'</urlset>')
(out/'robots.txt').write_text('User-agent: *\n'+('Allow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n' if args.production else 'Disallow: /\n'))
print(f'Built {len(paths)} static pages: {out}; production={args.production}; no deployment performed')
